WITH exploded AS (SELECT id, customer_id, coupon_codes, k, value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) li AS k, value), cleaned AS (SELECT id, coupon_codes, value, SORT_ARRAY(coupon_codes) AS sorted_coupon_codes FROM exploded WHERE k IS NOT NULL), valid AS (SELECT *, ARRAY_JOIN(coupon_codes, ', ') AS coupon_codes_text FROM cleaned WHERE SIZE(sorted_coupon_codes) > 1), base AS (SELECT *, ARRAY_JOIN(sorted_coupon_codes, '|') AS sorted_coupon_codes_text, SIZE(sorted_coupon_codes) AS sorted_coupon_codes_count FROM valid WHERE SIZE(coupon_codes) > 1), enriched AS (SELECT *, PERCENT_RANK() OVER (ORDER BY sorted_coupon_codes_count) AS sorted_coupon_codes_count_percent_rank, DENSE_RANK() OVER (ORDER BY sorted_coupon_codes_count) AS sorted_coupon_codes_count_dense_rank, RANK() OVER (ORDER BY sorted_coupon_codes_count DESC) AS sorted_coupon_codes_count_rank FROM base) SELECT coupon_codes, value, sorted_coupon_codes, coupon_codes_text, sorted_coupon_codes_text, sorted_coupon_codes_count, sorted_coupon_codes_count_dense_rank, sorted_coupon_codes_count_rank FROM enriched;
